<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link href="<?= base_url('assets/css/styles.css') ?>" rel="stylesheet"><title>Meu perfil</title></head><body><main class="container py-5" style="max-width:900px"><div class="d-flex justify-content-between align-items-start mb-4"><div><h1>Meu perfil</h1><p class="text-muted">Você pode alterar somente as suas informações públicas.</p></div><form method="post" action="<?= base_url('meu-perfil/sair') ?>"><?= csrf_field() ?><button class="btn btn-outline-secondary">Sair</button></form></div><?php if (session('success')) : ?><div class="alert alert-success"><?= esc(session('success')) ?></div><?php endif ?><?php if (session('error')) : ?><div class="alert alert-danger"><?= esc(session('error')) ?></div><?php endif ?><?php $gallery = json_decode((string) ($instrutor['fotos'] ?? '[]'), true) ?: []; ?><?php if (!empty($instrutor['foto_perfil']) || $gallery) : ?><section class="card p-4 mb-4"><h2 class="h4">Minhas fotos</h2><div class="d-flex flex-wrap gap-3 align-items-start"><?php if (!empty($instrutor['foto_perfil'])) : ?><div><img src="<?= base_url('uploads/' . $instrutor['foto_perfil']) ?>" alt="Minha foto de perfil" style="width:150px;height:150px;object-fit:cover;border-radius:50%"><form class="mt-2" method="post" action="<?= base_url('meu-perfil/foto/excluir') ?>"><?= csrf_field() ?><input type="hidden" name="tipo" value="perfil"><input type="hidden" name="foto" value="<?= esc($instrutor['foto_perfil'], 'attr') ?>"><button class="btn btn-sm btn-outline-danger" onclick="return confirm('Excluir a foto de perfil?')">Excluir foto de perfil</button></form></div><?php endif ?><?php foreach ($gallery as $photo) : ?><div><img src="<?= base_url('uploads/' . $photo) ?>" alt="Foto da galeria" style="width:150px;height:110px;object-fit:cover;border-radius:8px"><form class="mt-2" method="post" action="<?= base_url('meu-perfil/foto/excluir') ?>"><?= csrf_field() ?><input type="hidden" name="tipo" value="galeria"><input type="hidden" name="foto" value="<?= esc($photo, 'attr') ?>"><button class="btn btn-sm btn-outline-danger" onclick="return confirm('Excluir esta foto?')">Excluir</button></form></div><?php endforeach ?></div></section><?php endif ?><form method="post" enctype="multipart/form-data" class="card p-4"><?= csrf_field() ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Nome completo</label><input class="form-control" name="nome" maxlength="150" value="<?= esc(old('nome', $instrutor['nome']), 'attr') ?>" required></div><div class="col-md-3"><label class="form-label">Apelido</label><input class="form-control" name="apelido" maxlength="100" value="<?= esc(old('apelido', $instrutor['apelido']), 'attr') ?>" required></div><div class="col-md-3"><label class="form-label">Graduação</label><select class="form-select" name="graduacao" required><?php foreach ($graduacoes as $graduacao) : ?><option value="<?= esc($graduacao, 'attr') ?>" <?= old('graduacao', $instrutor['graduacao']) === $graduacao ? 'selected' : '' ?>><?= esc($graduacao) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">E-mail de acesso</label><input class="form-control" value="<?= esc($instrutor['email'], 'attr') ?>" disabled></div><div class="col-md-6"><label class="form-label">WhatsApp</label><input class="form-control" name="whatsapp" maxlength="30" value="<?= esc(old('whatsapp', $instrutor['whatsapp']), 'attr') ?>"></div><div class="col-md-6"><label class="form-label">Foto de perfil</label><input class="form-control" type="file" name="foto_perfil" accept="image/jpeg,image/png,image/webp"></div><div class="col-md-6"><label class="form-label">Adicionar fotos à galeria</label><input class="form-control" type="file" name="fotos[]" accept="image/jpeg,image/png,image/webp" multiple></div><div class="col-12"><label class="form-label">Biografia</label><textarea class="form-control" name="biografia" rows="6" maxlength="5000"><?= esc(old('biografia', $instrutor['biografia'])) ?></textarea></div></div><hr class="my-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h4 mb-0">Locais de aula</h2><small class="text-muted">O endereço atualiza o ponto do mapa automaticamente.</small></div><button class="btn btn-outline-primary" id="adicionar-local" type="button">Adicionar local</button></div><div id="locais"><?php foreach ($locais ?: [['nome' => '', 'endereco' => '', 'dias_horarios' => '']] as $local) : ?><div class="local border rounded p-3 mb-3"><div class="row g-3"><div class="col-md-4"><label class="form-label">Nome</label><input class="form-control" name="local_nome[]" value="<?= esc($local['nome'], 'attr') ?>"></div><div class="col-md-8"><label class="form-label">Endereço</label><input class="form-control" name="local_endereco[]" value="<?= esc($local['endereco'] ?? '', 'attr') ?>"></div><div class="col-md-9"><label class="form-label">Dias e horários</label><input class="form-control" name="local_dias_horarios[]" value="<?= esc($local['dias_horarios'] ?? '', 'attr') ?>"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-outline-danger remover" type="button">Remover</button></div></div></div><?php endforeach ?></div><template id="local-template"><div class="local border rounded p-3 mb-3"><div class="row g-3"><div class="col-md-4"><label class="form-label">Nome</label><input class="form-control" name="local_nome[]"></div><div class="col-md-8"><label class="form-label">Endereço</label><input class="form-control" name="local_endereco[]"></div><div class="col-md-9"><label class="form-label">Dias e horários</label><input class="form-control" name="local_dias_horarios[]"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-outline-danger remover" type="button">Remover</button></div></div></div></template><button class="btn btn-primary mt-2">Salvar alterações</button></form></main><script>document.getElementById('adicionar-local').onclick=()=>document.getElementById('locais').append(document.getElementById('local-template').content.cloneNode(true));document.getElementById('locais').onclick=e=>{if(e.target.classList.contains('remover'))e.target.closest('.local').remove()};</script></body></html>
